package com.servicedesk360.service;
import com.servicedesk360.dto.task.TaskStatusRequest; import com.servicedesk360.entity.*; import com.servicedesk360.repository.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.util.Optional; import static org.assertj.core.api.Assertions.assertThatThrownBy; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class TaskServiceTest{ @Mock TaskRepository tasks; @Mock UserRepository users; @Mock TicketRepository tickets; @Mock CurrentUserService current; @Mock NotificationService notifications; @InjectMocks TaskService service;
 @Test void rejectsInvalidTaskTransition(){Task t=mock(Task.class); User u=mock(User.class); when(t.getStatus()).thenReturn(TaskStatus.DONE); when(current.getRequiredUser()).thenReturn(new CurrentUserService.CurrentUser(u,1L,Role.MANAGER)); when(tasks.findByIdAndTenantId(1L,1L)).thenReturn(Optional.of(t)); assertThatThrownBy(()->service.status(1L,new TaskStatusRequest(TaskStatus.IN_PROGRESS))).isInstanceOf(com.servicedesk360.exception.BusinessException.class);}}
